import csv

ts_refs = {
    "Core_bottom": "134c4f67-a2ef-5cd4-b03a-f18a5601c587",
    "Perimeter_bot_ZN_4": "b3c1fa84-57dc-5f64-86f8-566814470faa",
    "Perimeter_top_ZN_1": "752938fd-1330-5407-9a4f-66e1191a232a"
}

date_str = "2018-10-12"
energies = {}

with open(VALUES_CSV, 'r') as f:
    reader = csv.reader(f)
    next(reader) # skip header
    for row in reader:
        ts_id, timestamp, value = row
        if timestamp.startswith(date_str):
            for zone, uid in ts_refs.items():
                if ts_id == uid:
                    energies[zone] = energies.get(zone, 0) + float(value)

print(energies)
